def get_taxonomic_order(species_name):
    if species_name in orders_cache:
        return orders_cache[species_name]

    try:
        search_handle = Entrez.esearch(db="taxonomy", term=species_name)
        search_results = Entrez.read(search_handle)
        search_handle.close()
        if search_results["IdList"]:
            tax_id = search_results["IdList"][0]
            fetch_handle = Entrez.efetch(db="taxonomy", id=tax_id, retmode="xml")
            taxonomic_data = Entrez.read(fetch_handle)
            fetch_handle.close()
            for rank in taxonomic_data[0]["LineageEx"]:
                if rank["Rank"] == "order":
                    order_name = rank["ScientificName"]
                    orders_cache[species_name] = order_name
                    return order_name
    except Exception as e:
        print(f"Ошибка для {species_name}: {e}")

    orders_cache[species_name] = "Unknown"
    return "Unknown"

